from datetime import datetime


def group_digits(digits: str, sizes, sep: str, min_grouping: int) -> str:
    """Groups integer digits from the right with the locale's group sizes (section 7.3)."""
    if len(digits) < sizes[0] + min_grouping:
        return digits
    groups = []
    rest = digits
    i = 0
    while rest:
        size = sizes[min(i, len(sizes) - 1)]
        groups.append(rest[-size:])
        rest = rest[:-size]
        i += 1
    return sep.join(reversed(groups))


def number_text(value, scale: int, locale, grouping: bool) -> str:
    if scale:
        text = f"{value.copy_abs():.{scale}f}"
    else:
        text = str(abs(value))
    whole, _, frac = text.partition(".")
    negative = value < 0 and any(c != "0" for c in whole + frac)
    if locale is None:
        return ("-" if negative else "") + text
    if grouping:
        whole = group_digits(whole, locale.group_sizes, locale.group, locale.min_grouping)
    body = whole + (locale.decimal + frac if scale else "")
    return (locale.minus if negative else "") + body


_TOKENS = ("YYYY", "MM", "DD", "HH", "hh", "mm", "ss", "M", "D", "H", "h", "A")


def pattern_text(value, pattern: str) -> str:
    """A date or datetime written with a locale pattern (section 7.4)."""
    is_dt = isinstance(value, datetime)
    hour = value.hour if is_dt else 0
    parts = {
        "YYYY": f"{value.year:04d}",
        "MM": f"{value.month:02d}",
        "M": str(value.month),
        "DD": f"{value.day:02d}",
        "D": str(value.day),
    }
    if is_dt:
        h12 = hour % 12 or 12
        parts.update({
            "HH": f"{hour:02d}",
            "H": str(hour),
            "hh": f"{h12:02d}",
            "h": str(h12),
            "mm": f"{value.minute:02d}",
            "ss": f"{value.second:02d}",
            "A": "AM" if hour < 12 else "PM",
        })
    out = []
    i = 0
    while i < len(pattern):
        for tok in sorted(parts, key=len, reverse=True):
            if pattern.startswith(tok, i):
                out.append(parts[tok])
                i += len(tok)
                break
        else:
            out.append(pattern[i])
            i += 1
    return "".join(out)


def value_text(value, field, locale, grouping: bool) -> str:
    """Text of a non-null typed value."""
    t = field.type
    if t == "string":
        return value
    if t == "int":
        return number_text(value, 0, locale, grouping)
    if t == "decimal":
        return number_text(value, field.scale, locale, grouping)
    if t == "bool":
        if locale is None:
            return "true" if value else "false"
        return locale.true if value else locale.false
    if t == "date":
        if locale is None:
            return f"{value.year:04d}-{value.month:02d}-{value.day:02d}"
        return pattern_text(value, locale.date)
    if isinstance(value, datetime):
        if locale is None:
            return (f"{value.year:04d}-{value.month:02d}-{value.day:02d}"
                    f"T{value.hour:02d}:{value.minute:02d}:{value.second:02d}Z")
        return pattern_text(value, locale.datetime)
    raise ValueError(f"no text for {t}")
